<script setup lang="ts">
/**
 * Kamp.la ikon seti.
 *
 * GÜNCELLEME (2026-07-26, gerçek export entegrasyonu): Bu bileşen önceki bir
 * oturumda Figma screenshot'larına bakılarak ELLE YAKINSANMIŞ (gerçek export
 * OLMAYAN) SVG path'leri içeriyordu — Mustafa bunu fark etti, ciddi bir
 * dürüstlük hatasıydı çünkü kendisi zaten TÜM ikonları Figma'dan export edip
 * `design/icons-export/*.svg` altına koymuştu. Bu path'ler artık o gerçek
 * export dosyalarından birebir kopyalanmıştır (bkz. FIGMA.md — "önce HER
 * ZAMAN icons-export/ klasörüne bak" kuralı). Renk kuralı: kullanım yerinde
 * dinamik renk gerekiyorsa (ör. favori kalp state'i, seçili filtre kartı
 * beyaz/turuncu geçişi) export'un sabit hex'i `currentColor`'a çevrildi;
 * Figma'da zaten sabit/çok renkli tasarlanmış ikonlarda (yıldız: dolu sarı
 * #FFCA41 / boş gri #EEEEEE — PRD'deki `ratingColor` ile birebir aynı) sabit
 * hex korundu.
 *
 * BİLİNEN EKSİK: `search` (büyüteç) için 118 export dosyası arasında AYRI bir
 * SVG YOK — Figma ekran görüntülerinde ("10-Arama Ekranı.png", alt nav'daki
 * büyüteç) ikon görünüyor ama `design/icons-export/` klasöründe tek başına
 * export edilmemiş. Kafadan uydurmamak için bu isim hâlâ elle yakınsanmış bir
 * yaklaşıklık kullanıyor — Mustafa'nın Figma'dan bu tek node'u ayrıca export
 * etmesi gerekiyor (bkz. BLOCKERS.md).
 */
export type IconName =
  | "heart-line"
  | "heart-solid"
  | "star-solid"
  | "star-line"
  | "filter"
  | "locate"
  | "map"
  | "close"
  | "search"
  | "back"
  | "pin"
  | "fee-badge"
  | "poi-caravan"
  | "poi-parking"
  | "poi-tent"
  | "poi-water"
  | "poi-laundry"
  | "poi-shower";

const props = withDefaults(defineProps<{ name: IconName }>(), {});
void props;
</script>

